public class InventoryManager
{
    private readonly Dictionary<Guid, int> _stock = new();
    private readonly HashSet<Guid> _lowStockAlert = new();

    public void Deduct(Guid productId, int quantity)
    {
        _stock[productId] -= quantity;
        if (_stock[productId] < 10 && !_lowStockAlert.Contains(productId))
        {
            _lowStockAlert.Add(productId);
            _notifier.NotifyLowStock(productId, _stock[productId]);
        }
    }
}

public class RecommendationEngine
{
    public IEnumerable<Product> GetRecommendations(Guid userId)
    {
        var userPurchases = _orders.Where(o => o.UserId == userId)
            .SelectMany(o => o.Items.Select(i => i.ProductId))
            .ToHashSet();

        // Simple: recommend products in same categories as purchases
        var categories = _products
            .Where(p => userPurchases.Contains(p.Id))
            .Select(p => p.CategoryId)
            .Distinct();

        return _products
            .Where(p => categories.Contains(p.CategoryId) && !userPurchases.Contains(p.Id))
            .OrderByDescending(p => p.Rating)
            .Take(10);
    }
}
